#!/usr/bin/env node
/**
 * Generates MCP tool definitions from each package OpenAPI spec using
 * openapi-mcp-generator (getToolsFromOpenApi) — tools only, no MCP server scaffold.
 * @see https://github.com/harsha-iiiv/openapi-mcp-generator
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { getToolsFromOpenApi } from 'openapi-mcp-generator';
import { packages } from './packages.ts';

const banner = `/**
 * OpenAPI-derived MCP tool definitions.
 * @generated by scripts/generate-openapi-mcp-tools.mjs — do not edit.
 * @see https://github.com/harsha-iiiv/openapi-mcp-generator
 */
`;

const indexBanner = `/**
 * MCP tool definitions extracted from the package OpenAPI spec (openapi-mcp-generator).
 * @generated by scripts/generate-openapi-mcp-tools.mjs
 */
`;

export async function generateMcpTools() {
  for (const { name, packagePath, specPath } of packages) {
    const outDir = join(packagePath, 'src', 'tools');
    process.stdout.write(`generate-openapi-mcp-tools: ${name} … `);
    const tools = await getToolsFromOpenApi(specPath, { dereference: true });
    const json = JSON.stringify(tools, null, 2);
    await mkdir(outDir, { recursive: true });
    await writeFile(join(outDir, 'openapi-tools.json'), `${json}\n`, 'utf8');
    await writeFile(
      join(outDir, 'openapi-tools.gen.ts'),
      `${banner}export const openapiMcpTools = ${json} as const;

  export type OpenapiMcpTool = (typeof openapiMcpTools)[number];
  `,
      'utf8'
    );
    await writeFile(
      join(outDir, 'index.ts'),
      `${indexBanner}export type { OpenapiMcpTool } from './openapi-tools.gen.js';
  export { openapiMcpTools } from './openapi-tools.gen.js';
  `,
      'utf8'
    );
    console.log(`${tools.length} tools`);
  }
}
